import {expect,it} from 'vitest';
import {deferred,stateRow,syntheticHarness} from '../tests/phase2a03/transaction-fake';
import {transactionSql} from '../src/server/location/transaction.server';
it('AUDIT-F01: rejecting an already reserved object must not discard its active owner connection',async()=>{
 const h=await syntheticHarness();
 const entered=deferred(),finish=deferred();
 h.client.hooks.set('commit',async()=>{entered.resolve();await finish.promise;});
 const first=h.run(); await entered.promise;
 const before=h.client.transcript.length;
 const second=await h.run();
 const intervening=h.client.transcript.slice(before).map(e=>e.kind);
 finish.resolve(); await first;
 console.log(JSON.stringify({finding:'AUDIT-F01',second,intervening}));
 expect(second).toMatchObject({kind:'FAILURE',code:'TRANSACTION_FAILED'});
 expect(intervening).toEqual(['acquire']);
});
it('AUDIT-G01: fake CAS does not enforce the SQL property_id predicate (coverage limitation)',async()=>{
 const h=await syntheticHarness();
 h.store.state=stateRow();
 const options={signal:new AbortController().signal,timeoutMs:1000};
 await h.client.query(transactionSql.begin,[],options);
 const wrong='f9000000-0000-0000-0000-000000000009';
 const result=await h.client.query(transactionSql.cas,[wrong,wrong,0,null],options);
 expect(result.rowCount).toBe(1); // actual WHERE property_id=$1 would match zero rows
 await h.client.rollback(options);
});
